const NUCLEATION = { "Sparse trickle": 3, "Steady bubbling": 6, "Dense churn": 12, "Furious boiling": 20, "Hyperactive swarm": 35, "Rupturing flood": 50 };
const GROWTH = { "Glacial crawl": 0.2, "Organic pulse": 0.5, "Brisk swelling": 1.0, "Volatile surge": 1.8, "Explosive frenzy": 3.0, "Instantaneous blast": 5.0 };
const THRESHOLD = { "Microscopic speckles": 60, "Pebble fractures": 85, "Chamber ruptures": 110, "Giant cauldrons": 150, "Monolithic voids": 210, "Cataclysmic collapse": 290 };
const VORTEX = { "Zero drift": 0, "Subtle eddy": 0.002, "Winding spiral": 0.006, "Torqued gyre": 0.015, "Furious maelstrom": 0.03, "Tearing cyclone": 0.06 };
const STYLES = {
    "High contrast monochrome": { bg: [20], fill: [240, 240, 240, 255], stroke: [20, 20, 20, 255], weight: 2 },
    "Inverted stark voids": { bg: [240], fill: [20, 20, 20, 255], stroke: [240, 240, 240, 255], weight: 2 },
    "Bioluminescent rims": { bg: [5, 10, 15], fill: [0, 50, 40, 150], stroke: [0, 255, 200, 255], weight: 3 },
    "Deep chromatic halos": { bg: [10, 5, 30], fill: [255, 50, 150, 100], stroke: [50, 200, 255, 255], weight: 2 },
    "X-ray radiogram": { bg: [0], fill: [50, 70, 100, 80], stroke: [200, 220, 255, 255], weight: 2 },
    "Molten thermals": { bg: [30, 0, 0], fill: [200, 50, 0, 200], stroke: [255, 200, 0, 255], weight: 2 }
};

let bubbles = [];
let gridSize = 60;
let cols, rows;

p.setup = function() {
    p.createCanvas(800, 800);
    cols = Math.ceil(p.width / gridSize);
    rows = Math.ceil(p.height / gridSize);
    p.noStroke();

    for (let i = 0; i < 120; i++) {
        bubbles.push({
            x: p.random(p.width),
            y: p.random(p.height),
            r: p.random(15, 35),
            vx: 0,
            vy: 0,
            gridX: 0,
            gridY: 0
        });
    }
};

p.draw = function() {
    const nuc = p.getSynthVar('nucleation_rate') || 'Steady bubbling';
    const gro = p.getSynthVar('growth_velocity') || 'Brisk swelling';
    const thr = p.getSynthVar('burst_threshold') || 'Chamber ruptures';
    const vor = p.getSynthVar('vortex_torque') || 'Winding spiral';
    const ren = p.getSynthVar('render_viscosity') || 'Inverted stark voids';

    const spawnCount = NUCLEATION[nuc];
    const growthRate = GROWTH[gro];
    const maxRadius = THRESHOLD[thr];
    const torque = VORTEX[vor];
    const style = STYLES[ren];

    let grid = new Array(cols * rows).fill(null).map(() => []);

    for (let i = bubbles.length - 1; i >= 0; i--) {
        let b = bubbles[i];
        b.r += growthRate;

        if (b.r > maxRadius) {
            bubbles.splice(i, 1);
            continue;
        }

        b.x += b.vx;
        b.y += b.vy;
        b.vx *= 0.85;
        b.vy *= 0.85;

        if (torque > 0) {
            let dx = b.x - p.width / 2;
            let dy = b.y - p.height / 2;
            b.vx -= dy * torque;
            b.vy += dx * torque;
        }

        if (b.x < 0) { b.x = 0; b.vx *= -0.5; }
        if (b.x > p.width) { b.x = p.width; b.vx *= -0.5; }
        if (b.y < 0) { b.y = 0; b.vy *= -0.5; }
        if (b.y > p.height) { b.y = p.height; b.vy *= -0.5; }

        let cx = Math.floor(b.x / gridSize);
        let cy = Math.floor(b.y / gridSize);
        if (cx >= 0 && cx < cols && cy >= 0 && cy < rows) {
            grid[cx + cy * cols].push(b);
            b.gridX = cx;
            b.gridY = cy;
        }
    }

    for (let i = 0; i < bubbles.length; i++) {
        let b = bubbles[i];
        for (let ox = -1; ox <= 1; ox++) {
            for (let oy = -1; oy <= 1; oy++) {
                let nx = b.gridX + ox;
                let ny = b.gridY + oy;
                if (nx >= 0 && nx < cols && ny >= 0 && ny < rows) {
                    let cell = grid[nx + ny * cols];
                    for (let j = 0; j < cell.length; j++) {
                        let other = cell[j];
                        if (other !== b) {
                            let dx = b.x - other.x;
                            let dy = b.y - other.y;
                            let distSq = dx * dx + dy * dy;
                            let minDist = b.r + other.r;
                            if (distSq < minDist * minDist && distSq > 0) {
                                let dist = Math.sqrt(distSq);
                                let overlap = (minDist - dist) * 0.5;
                                let fx = (dx / dist) * overlap * 0.5;
                                let fy = (dy / dist) * overlap * 0.5;
                                b.vx += fx;
                                b.vy += fy;
                            }
                        }
                    }
                }
            }
        }
    }

    let requiredSpawns = Math.max(spawnCount, 60 - bubbles.length);
    for (let i = 0; i < requiredSpawns; i++) {
        if (bubbles.length < 180) {
            bubbles.push({
                x: p.random(p.width),
                y: p.random(p.height),
                r: p.random(15, 35),
                vx: 0,
                vy: 0,
                gridX: 0,
                gridY: 0
            });
        }
    }

    p.drawingContext.globalCompositeOperation = 'source-over';
    p.background(...style.bg);

    p.fill(...style.fill);
    p.stroke(...style.stroke);
    p.strokeWeight(style.weight);

    p.drawingContext.beginPath();
    for (let i = 0; i < bubbles.length; i++) {
        let b = bubbles[i];
        p.drawingContext.moveTo(b.x + b.r, b.y);
        p.drawingContext.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    }
    p.drawingContext.fill();
    p.drawingContext.stroke();
};
